          "mondaiName": "韓国本専門: 文法形式の判断",
          "type": "grammar",
          "question": "この店でコーヒーを飲む時は、いつも店の横に自転車を（　　）。",
          "options": [
            "おかれてくれていた",
            "おかれていた",
            "おかせてもらってきた",
            "おかせていただいた"
          ],
          "correctAnswer": 4,
          "explanation": "<b>おかせていただいた（置かせていただいた）：</b>Được phép để xe nhờ vào đó (khiêm nhường ngữ thể hiện sự biết ơn vì được cho phép).<br><b>Dịch nghĩa:</b> Mỗi lần uống cà phê ở quán này, tôi đều được phép để nhờ xe đạp ngay bên hông quán.<br><i>Phân tích các phương án:</i><br>• 1. おかれてくれていた: Sai cấu trúc kết hợp động từ<br>• 2. おかれていた: Được để (bị động thông thường)<br>• 3. おかせてもらってきた: Đã được cho phép (không trang trọng lịch sự bằng いただいた)<br>• <b>4. おかせていただいた: [Đúng] Khiêm nhường ngữ trang trọng: được cho phép để nhờ xe</b>"
