          "type": "grammar",
          "question": "最初は話すのが恥ずかしかったが、アルバイトを続けている（　　）お客さんとも親しくなった。",
          "options": [
            "うちに",
            "ときに",
            "おりに",
            "ついでに"
          ],
          "correctAnswer": 1,
          "explanation": "<b>V-ているうちに：</b>Trong quá trình làm liên tục..., dần dà trở nên...<br><b>Dịch nghĩa:</b> Lúc đầu tôi thấy rất ngại ngùng khi giao tiếp, nhưng trong quá trình tiếp tục làm thêm ở đây, tôi dần trở nên thân thiết với các khách hàng.<br><i>Phân tích các phương án:</i><br>• <b>1. うちに: [Đúng] 続けているうちに (trong quá trình làm liên tục thì dần quen và thân thiết)</b><br>• 2. ときに: Vào lúc<br>• 3. おりに: Nhân dịp, vào cơ hội<br>• 4. ついでに: Tiện thể làm gì thì làm thêm"
